#!/usr/bin/env bash
set -euo pipefail

AWS_REGION='us-east-1'
DEPLOYMENT_ENV='/opt/telecom-cicd/deployment.env'
ENV_DIRECTORY='/etc/telecom-cicd'

if [[ ! -f "$DEPLOYMENT_ENV" ]]; then
    echo 'deployment.env missing' >&2
    exit 1
fi
# deployment.env is generated by Jenkins and contains only IMAGE_URI/IMAGE_TAG.
# shellcheck disable=SC1090
source "$DEPLOYMENT_ENV"
if [[ -z "${IMAGE_URI:-}" ]]; then
    echo 'IMAGE_URI missing' >&2
    exit 1
fi

ACCOUNT_ID=$(aws sts get-caller-identity --query Account --output text)
ECR_REGISTRY="${ACCOUNT_ID}.dkr.ecr.${AWS_REGION}.amazonaws.com"

# Pull before disrupting the currently running container.
echo "Pulling image ${IMAGE_URI}"
aws ecr get-login-password --region "$AWS_REGION" | \
    docker login --username AWS --password-stdin "$ECR_REGISTRY"
docker pull "$IMAGE_URI"

# Keep secrets outside CodeDeploy's revision destination, with restrictive permissions.
install -d -m 700 "$ENV_DIRECTORY"
SECRET_JSON=$(aws secretsmanager get-secret-value \
    --secret-id telecom-cicd/app \
    --region "$AWS_REGION" \
    --query SecretString --output text)
# Avoid logging secret contents; reject multiline entries unsuitable for --env-file.
printf '%s' "$SECRET_JSON" | python3 -c '
import json, os, sys
values = json.load(sys.stdin)
keys = ("DB_USERNAME", "DB_PASSWORD", "BILLING_API_KEY")
for key in keys:
    value = values.get(key)
    if not isinstance(value, str) or "\n" in value or "\r" in value or "\0" in value:
        raise SystemExit("Required secret is missing or has unsupported characters: " + key)
p = "/etc/telecom-cicd/app.env"
fd = os.open(p, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
with os.fdopen(fd, "w") as fh:
    for key in keys:
        fh.write(key + "=" + values[key] + "\n")
'
chmod 600 "$ENV_DIRECTORY/app.env"
unset SECRET_JSON

# Prevent an old container with the expected name from blocking new docker run.
echo 'Replacing telecom container...'
docker rm -f telecom-cicd-pipeline >/dev/null 2>&1 || true
docker run -d \
    --name telecom-cicd-pipeline \
    --restart unless-stopped \
    --env-file "$ENV_DIRECTORY/app.env" \
    -p 5000:5000 \
    "$IMAGE_URI"
echo 'Container started; ValidateService will check its image and health.'
